<?php
require_once __DIR__ . '/../includes/init.php'; requireAdmin(); $pdo=db();
if ($_SERVER['REQUEST_METHOD']==='POST') {
 verifyCsrf(); $action=$_POST['action']??'';
 if ($action==='delete') { $id=(int)($_POST['id']??0); $s=$pdo->prepare('SELECT COUNT(*) FROM stock_movements WHERE item_id=?'); $s->execute([$id]); if($s->fetchColumn()>0) flash('error','This item has stock movement records and cannot be deleted.'); else { $d=$pdo->prepare('DELETE FROM items WHERE id=?'); $d->execute([$id]); flash('success','Item deleted.'); } redirect('admin/items.php'); }
 if ($action==='save') { $id=(int)($_POST['id']??0); $code=strtoupper(trim((string)($_POST['item_code']??''))); $name=trim((string)($_POST['item_name']??'')); $category=trim((string)($_POST['category']??'')); $location=trim((string)($_POST['location']??'')); $unit=trim((string)($_POST['unit']??'')); $qty=filter_var($_POST['quantity']??null,FILTER_VALIDATE_INT); $reorder=filter_var($_POST['reorder_level']??null,FILTER_VALIDATE_INT);
  if(!$code||!$name||!$category||!$location||!$unit||$qty===false||$qty===null||$qty<0||$reorder===false||$reorder===null||$reorder<0) flash('error','Complete all fields and use non-negative whole numbers for quantities.'); else { try { if($id){$s=$pdo->prepare('UPDATE items SET item_code=?,item_name=?,category=?,location=?,quantity=?,unit=?,reorder_level=? WHERE id=?'); $s->execute([$code,$name,$category,$location,$qty,$unit,$reorder,$id]); flash('success','Item updated.');} else {$s=$pdo->prepare('INSERT INTO items(item_code,item_name,category,location,quantity,unit,reorder_level) VALUES(?,?,?,?,?,?,?)');$s->execute([$code,$name,$category,$location,$qty,$unit,$reorder]);flash('success','Item created.');} } catch(PDOException $e){flash('error',$e->getCode()==='23000'?'That item code is already in use.':'Unable to save item.');} }
  redirect('admin/items.php'); }
}
$edit=null; if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM items WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}
$search=trim((string)($_GET['q']??''));$category=trim((string)($_GET['category']??''));$sql='SELECT * FROM items WHERE 1=1';$params=[];if($search!==''){$sql.=' AND (item_code LIKE :q1 OR item_name LIKE :q2 OR location LIKE :q3)';$params['q1']="%$search%";$params['q2']="%$search%";$params['q3']="%$search%";}if($category!==''){$sql.=' AND category=:category';$params['category']=$category;}$sql.=' ORDER BY item_name';$stmt=$pdo->prepare($sql);$stmt->execute($params);$rows=$stmt->fetchAll();$categories=itemCategories();$title='Items';$active='items';layoutStart($title,$active);
?><div class="page-heading"><div><div class="eyebrow">INVENTORY</div><h1>Items</h1><p>Manage item details and monitor stock levels.</p></div><a class="button primary" href="#item-form">＋ Add item</a></div>
<?php if($edit): ?><section class="panel form-panel" id="item-form"><div class="panel-heading"><div><h2>Edit item</h2><p>Update inventory details.</p></div><a class="icon-button" href="<?= e(url('admin/items.php')) ?>">×</a></div><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?= e(csrfToken()) ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= e($edit['id']) ?>"><?php foreach(['item_code'=>'Item code','item_name'=>'Item name','category'=>'Category','location'=>'Location','quantity'=>'Quantity','unit'=>'Unit','reorder_level'=>'Reorder level'] as $key=>$label): ?><label><?= e($label) ?><input name="<?= e($key) ?>" value="<?= e($edit[$key]) ?>" <?= in_array($key,['quantity','reorder_level'])?'type="number" min="0" step="1"':'required' ?> required></label><?php endforeach; ?><div class="form-actions"><button class="button primary">Save changes</button><a class="button light" href="<?= e(url('admin/items.php')) ?>">Cancel</a></div></form></section><?php else: ?><details class="panel collapsible" id="item-form"><summary><span><b>Add new item</b><small>Create a new inventory record</small></span><span class="button primary compact">＋ Add item</span></summary><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?= e(csrfToken()) ?>"><input type="hidden" name="action" value="save"><?php foreach(['item_code'=>'Item code','item_name'=>'Item name','category'=>'Category','location'=>'Location','quantity'=>'Quantity','unit'=>'Unit','reorder_level'=>'Reorder level'] as $key=>$label): ?><label><?= e($label) ?><input name="<?= e($key) ?>" <?= in_array($key,['quantity','reorder_level'])?'type="number" min="0" step="1" value="0"':'required' ?> required></label><?php endforeach; ?><div class="form-actions"><button class="button primary">Create item</button></div></form></details><?php endif; ?>
<section class="panel"><form class="filter-bar" method="get"><label class="search-field"><span>⌕</span><input name="q" value="<?= e($search) ?>" placeholder="Search code, name or location"></label><select name="category"><option value="">All categories</option><?php foreach($categories as $c): ?><option <?= $category===$c?'selected':'' ?> value="<?= e($c) ?>"><?= e($c) ?></option><?php endforeach; ?></select><button class="button light">Filter</button><?php if($search||$category): ?><a class="text-link" href="<?= e(url('admin/items.php')) ?>">Clear</a><?php endif; ?></form><div class="table-wrap"><table><thead><tr><th>ID</th><th>Item</th><th>Category</th><th>Location</th><th>Quantity</th><th>Unit</th><th>Reorder</th><th>Updated</th><th>Actions</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="9" class="empty">No inventory items found.</td></tr><?php else: foreach($rows as $r): ?><tr><td><?= e($r['id']) ?></td><td><b><?= e($r['item_name']) ?></b><small class="subtext"><?= e($r['item_code']) ?></small></td><td><?= e($r['category']) ?></td><td><?= e($r['location']) ?></td><td><?php if($r['quantity']<=$r['reorder_level']): ?><span class="badge warning"><?= e($r['quantity']) ?></span><?php else: ?><?= e($r['quantity']) ?><?php endif; ?></td><td><?= e($r['unit']) ?></td><td><?= e($r['reorder_level']) ?></td><td><?= e(dateValue($r['updated_at'])) ?></td><td class="actions"><a class="text-link" href="<?= e(url('user/item-details.php?id='.$r['id'])) ?>">View</a><a class="text-link" href="<?= e(url('admin/items.php?edit='.$r['id'])) ?>">Edit</a><form method="post" data-confirm="Delete this item? Items with movement history cannot be deleted."><input type="hidden" name="csrf" value="<?= e(csrfToken()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= e($r['id']) ?>"><button class="link-danger">Delete</button></form></td></tr><?php endforeach; endif; ?></tbody></table></div><div class="table-foot"><?= count($rows) ?> item<?= count($rows)===1?'':'s' ?></div></section><?php layoutEnd(); ?>
